<script>
function toggleAction(id){document.querySelectorAll('.actionmenu').forEach(x=>{if(x.id!==id)x.classList.remove('open')});const el=document.getElementById(id);if(el)el.classList.toggle('open')}
function editSelectedMaster(type){const x=document.querySelector('.masterPick:checked');if(!x)return alert('Select one record first.');openMasterModal(type,x.value)}
function deleteSelectedMaster(type){const x=document.querySelector('.masterPick:checked');if(!x)return alert('Select one record first.');if(!confirm('Deactivate selected master record?'))return;const f=document.createElement('form');f.method='post';f.innerHTML='<input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_master"><input type="hidden" name="type" value="'+type+'"><input type="hidden" name="id" value="'+x.value+'">';document.body.appendChild(f);f.submit()}
function f(){const q=(document.getElementById('q')?.value||'').toLowerCase();document.querySelectorAll('#t tr').forEach((r,i)=>{if(i)r.style.display=r.innerText.toLowerCase().includes(q)?'':'none'})}
document.addEventListener('click',e=>{if(!e.target.closest('.actionbox'))document.querySelectorAll('.actionmenu').forEach(x=>x.classList.remove('open'));const tr=e.target.closest('#t tr');if(tr&&!e.target.closest('input,button,a,select,textarea')){const cb=tr.querySelector('.masterPick');if(cb){document.querySelectorAll('.masterPick').forEach(x=>x.checked=false);cb.checked=true;}}});document.querySelectorAll('.masterPick').forEach(cb=>cb.addEventListener('change',()=>{if(cb.checked)document.querySelectorAll('.masterPick').forEach(x=>{if(x!==cb)x.checked=false})}));
</script>

