<script>
/* defined on every load: "Edit Selected" (and a double-click on a row) must work before the edit window is open */
function closeMasterModal(){const u=new URL(window.location.href);u.searchParams.delete('add');u.searchParams.delete('edit');window.location.href=u.toString()}
function openMasterModal(type,id){const u=new URL(window.location.href);u.searchParams.set('add','1');u.searchParams.set('edit',id);u.searchParams.set('tab',type==='dc'?'dcs':type==='store'?'stores':type==='vehicle'?'vehicles':'drivers');window.location.href=u.toString()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('masterModal'))closeMasterModal()});
document.addEventListener('dblclick',e=>{const tr=e.target.closest('#t tr');const cb=tr&&tr.querySelector('.masterPick');if(cb&&!e.target.closest('input,button,a,select,textarea')){const tp=new URL(window.location.href).searchParams.get('tab')||'stores';openMasterModal(tp==='dcs'?'dc':tp==='stores'?'store':tp==='vehicles'?'vehicle':'driver',cb.value);}});
</script>

